async function play(vid) {
  listenEnd(false);   // the song being replaced: count it as a play or a skip
  const v = S.lib.versions.find(x => x.version_id === vid);
  if (!v) return;
  const t = trk(v.track_id), r = rel(t.release_id);
  S.now = { v, t, r, dl: '' };
  $('#mini').hidden = false;
  // iPhones only allow sound that starts inside the tap itself, so start a silent clip now
  // and swap in the real file when Drive is ready.
  if (!unlocked) { audio.src = SILENT; audio.play().then(() => (unlocked = true)).catch(() => {}); }
  updateNowUI();
  audio.pause();
  clearWatchdog(); releaseMem();
  const wasYt = S.ytSong; S.ytSong = isYtSong(v);
  if (S.ytSong) {   // no audio file: the YouTube video is the song
    msg(''); recordRecent(t); openNp(); setMode('video'); ytHello(); $('#npMode').hidden = true; return;
  }
  if (wasYt && S.videoMode) setMode('song');
  msg('Loading…');
  if (!S.streamKey && S.lib.stream_key) S.streamKey = S.lib.stream_key;
  warmRelease(r.release_id);
  try {
    const fid = songFile(v);
    let src = null, played = false;
    const pre = takePrefetched(vid);   // already in memory? start at once
    if (pre) {
      S.memUrl = pre.url; S.directTry = false; audio.src = pre.url;
      if (S.videoMode && videoOf(t)) { msg(''); recordRecent(t); return; }
      try { await audio.play(); played = true; }
      catch (e) { if (e && e.name === 'NotAllowedError') { msg('Tap play to start.'); setToggle(false); return; } }
    }
    if (!played) {
      src = await sourceFor(fid, true);
      if (S.now.v !== v) return;
      S.viaApi = src.viaApi;
      S.directTry = !!src.direct;              // a direct address that fails is retried quietly below
      audio.src = src.stream;
      if (S.videoMode && videoOf(t)) { S.directTry = false; msg(''); recordRecent(t); return; }   // watching the video: keep the song ready but silent
      try { await audio.play(); S.directTry = false; played = true; }
      catch (e) {
        if (e && e.name === 'NotAllowedError') { msg('Tap play to start.'); setToggle(false); return; }
        // Don't give up: fresh re-share of this file → the spare copy, if there is one → one more try after a moment.
        if (src && src.own) { (S.badFile = S.badFile || {})[fid] = 1; logErr('Own-storage copy failed, using Drive: ' + (t.title || vid)); }
        delete S.pub[fid];
        const alt = fid === v.preview ? v.audio : (v.preview && fid !== v.preview ? v.preview : '');
        const attempts = [[fid, false, true], ...(alt ? [[alt, true, false], [alt, false, true]] : []), [fid, false, true, 1200]];
        let lastErr = null;
        for (const [f, direct, force, wait] of attempts) {
          if (wait) await new Promise(r2 => setTimeout(r2, wait));
          if (S.now.v !== v) return;
          try { src = await sourceFor(f, direct, force); if (S.now.v !== v) return; audio.src = src.stream; await audio.play(); played = true; break; }
          catch (e2) { lastErr = e2; if (e2 && e2.name === 'NotAllowedError') break; if (isMissingFile(e2)) break; }
        }
        S.directTry = false;
        if (!played && isMissingFile(lastErr)) return songMissing(v);
        if (!played) {
          if (lastErr && lastErr.name === 'NotAllowedError') { msg('Tap play to start.'); setToggle(false); return; }
          if (await rescue(v, fid, 0)) played = true;      // whole song into memory, then MP3 on the phone
          else { songFailed(v, src && src.stream); return; }   // still no: on to the next song
        }
      }
    }
    S.failStreak = 0;
    prefetchCheck();
    msg('');
    recordRecent(t);
    if (BOOT.token && !S.played[vid]) { S.played[vid] = 1; run('recordPlay', BOOT.token).catch(() => {}); }
    if (OWNER || (S.share && S.share.allow_download)) {
      const dl = v.audio ? (await sourceFor(v.audio, true)).download : (src && src.download);
      if (S.now.v === v) { S.now.dl = dl || ''; updateNowUI(); }
    }
  } catch (e) {
    if (S.now && S.now.v === v) { if (isMissingFile(e)) songMissing(v); else songFailed(v, '', e && e.message); }
  }
}


function audioDuration(file) {   // seconds, read from the file's own header; null if the browser can't tell
  return new Promise(res => {
    try {
      const a = new Audio(), u = URL.createObjectURL(file);
      const done = d => { URL.revokeObjectURL(u); a.onloadedmetadata = a.onerror = null; a.removeAttribute('src'); res(isFinite(d) && d > 0 ? d : null); };
      a.preload = 'metadata'; a.onloadedmetadata = () => done(a.duration); a.onerror = () => done(null); setTimeout(() => done(null), 8000); a.src = u;
    } catch (e) { res(null); }
  });
}


