/* The last-resort MP3 encoder is served from this project's own "Lame" file; the outside copy is only a fallback. */
const LAME_CDN = 'https://cdnjs.cloudflare.com/ajax/libs/lamejs/1.2.1/lame.min.js';
function loadLame() {
  if (window.lamejs) return Promise.resolve(window.lamejs);
  const load = src => new Promise((res, rej) => { const s = document.createElement('script'); s.src = src; s.onload = () => (window.lamejs ? res(window.lamejs) : rej(new Error('empty'))); s.onerror = () => rej(new Error('load')); document.head.appendChild(s); });
  const mine = [...document.scripts].find(s => /[?&]asset=app\b/.test(s.src)), own = mine ? mine.src.replace(/asset=app/, 'asset=lame') : '';
  return lameP || (lameP = (own ? load(own).catch(() => load(LAME_CDN)) : load(LAME_CDN)).catch(() => { lameP = null; throw new Error('Could not load the MP3 encoder. Check your connection.'); }));
}
/* Problems are reported once, not thousands of times: the same problem is sent at most once a minute, 10 a minute, 40 a visit. */
const errSeen = new Map(); let errWindow = { t: 0, n: 0 }, errTotal = 0;
function logErr(message, mode) {
  const msg = String(message || '').slice(0, 300), key = msg.replace(/[0-9a-f]{8,}/gi, '#').replace(/\d+/g, '#').slice(0, 120), now = Date.now();
  const last = errSeen.get(key); if (last && now - last < 60000) return Promise.resolve();
  if (now - errWindow.t > 60000) errWindow = { t: now, n: 0 };
  if (errWindow.n >= 10 || errTotal >= 40) return Promise.resolve();
  errSeen.set(key, now); errWindow.n++; errTotal++;
  return run('logClientError', msg, mode || (BOOT.token ? 'share' : 'owner')).catch(() => {});
}
